// Removes keys starting with "$" or containing "." to block NoSQL operator injection.
// Replaces express-mongo-sanitize, which is incompatible with Express 5.
const clean = (obj) => {
  if (obj && typeof obj === 'object') {
    for (const key of Object.keys(obj)) {
      if (key.startsWith('$') || key.includes('.')) {
        delete obj[key];
      } else {
        clean(obj[key]);
      }
    }
  }
  return obj;
};

const sanitize = (req, res, next) => {
  clean(req.body);
  next();
};

module.exports = sanitize;

require('dotenv').config();

const https = require('https');
const fs = require('fs');
const path = require('path');

const app = require('./app');
const connectDB = require('./config/db');
const { logger } = require('./utils/logger');

// fail fast instead of running with missing secrets (e.g. JWT signing with "undefined")
const missing = ['MONGO_URI', 'JWT_SECRET'].filter((name) => !process.env[name]);
if (missing.length) {
  logger.error('config.missing_env', { missing });
  process.exit(1);
}

// --- Start server over HTTPS ---
const PORT = process.env.PORT || 5000;
const CERT_DIR = process.env.CERT_DIR || path.join(__dirname, '..', 'certs');

const sslOptions = {
  key: fs.readFileSync(path.join(CERT_DIR, 'localhost-key.pem')),
  cert: fs.readFileSync(path.join(CERT_DIR, 'localhost.pem')),
};

process.on('unhandledRejection', (reason) => {
  logger.error('process.unhandledRejection', { error: reason?.message || String(reason), stack: reason?.stack });
});

process.on('uncaughtException', (err) => {
  logger.error('process.uncaughtException', { error: err.message, stack: err.stack });
  process.exit(1);
});

const start = async () => {
  await connectDB();
  https.createServer(sslOptions, app).listen(PORT, () => {
    logger.info('server.started', { port: Number(PORT), env: process.env.NODE_ENV });
  });
};

start();

const fs = require('fs');
const path = require('path');
const winston = require('winston');

// JSON lines with a timestamp, so logs can be searched or shipped to a log platform.
// Never pass passwords, password hashes or tokens into the logger.
const LOG_DIR = process.env.LOG_DIR || path.join(__dirname, '..', '..', 'logs');
const isTest = process.env.NODE_ENV === 'test';

const transports = [
  new winston.transports.Console({
    format: process.env.NODE_ENV === 'production'
      ? winston.format.json()
      : winston.format.combine(winston.format.colorize(), winston.format.simple()),
  }),
];

if (!isTest) {
  fs.mkdirSync(LOG_DIR, { recursive: true });
  transports.push(
    new winston.transports.File({ filename: path.join(LOG_DIR, 'app.log'), maxsize: 5 * 1024 * 1024, maxFiles: 5 }),
    new winston.transports.File({ filename: path.join(LOG_DIR, 'error.log'), level: 'error' }),
    new winston.transports.File({ filename: path.join(LOG_DIR, 'security.log'), level: 'warn' })
  );
}

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'http',
  silent: isTest,
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'hustlehub-api' },
  transports,
});

// common request context for every event: who, from where, which request
const requestMeta = (req) => ({
  requestId: req.id,
  ip: req.ip,
  userId: req.user?.id,
  method: req.method,
  path: req.originalUrl,
});

module.exports = { logger, requestMeta };

const { TAX_CONFIG, estimateTax } = require('../src/config/tax');

describe('estimateTax (SARS 2027 brackets)', () => {
  test('zero, negative and invalid income give no tax', () => {
    for (const income of [0, -100, 'abc', undefined]) {
      expect(estimateTax(income)).toMatchObject({ estimatedTax: 0, netIncome: 0, effectiveRate: 0 });
    }
  });

  test('income under the tax threshold pays nothing after the rebate', () => {
    // 18% of 90 000 = 16 200, less than the 17 820 rebate
    expect(estimateTax(90000)).toMatchObject({ grossTax: 16200, estimatedTax: 0, netIncome: 90000 });
  });

  test('first bracket: 18% minus rebate', () => {
    // 200 000 × 18% = 36 000 − 17 820 = 18 180
    expect(estimateTax(200000)).toMatchObject({
      grossTax: 36000, estimatedTax: 18180, netIncome: 181820, marginalRate: 0.18,
    });
  });

  test('second bracket uses base + rate on the amount above the threshold', () => {
    // 44 118 + 26% × (300 000 − 245 100) = 58 392 − 17 820 = 40 572
    const result = estimateTax(300000);
    expect(result).toMatchObject({ grossTax: 58392, estimatedTax: 40572, marginalRate: 0.26 });
    expect(result.effectiveRate).toBeCloseTo(0.1352, 4);
  });

  test('bracket edge value stays in the lower bracket', () => {
    expect(estimateTax(245100)).toMatchObject({ grossTax: 44118, marginalRate: 0.18 });
  });

  test('top bracket is 45%', () => {
    // 666 339 + 45% × (2 000 000 − 1 878 600) = 720 969 − 17 820 = 703 149
    expect(estimateTax(2000000)).toMatchObject({ grossTax: 720969, estimatedTax: 703149, marginalRate: 0.45 });
  });

  test('every bracket base matches the previous bracket at its upper edge', () => {
    for (let i = 1; i < TAX_CONFIG.brackets.length; i += 1) {
      const prev = TAX_CONFIG.brackets[i - 1];
      const expectedBase = prev.base + (prev.upTo - prev.above) * prev.rate;
      expect(Math.abs(TAX_CONFIG.brackets[i].base - expectedBase)).toBeLessThanOrEqual(1);
    }
  });
});
